// Call the version function and validate basic invariants without leaking pointers into the pool
const char *ver_cstr = defendnot_api::version();
// The API promises a non-null, read-only, static C string
FUZZ_ASSERT(ver_cstr != nullptr, "version() must return non-null");
// Conservatively verify there is a terminating NUL within a small bound to avoid unbounded scanning
size_t limit = 128; size_t i = 0; while (i < limit && ver_cstr[i] != '\0') { ++i; }
FUZZ_ASSERT(i < limit, "version() string appears unterminated within sanity bound");
// Do not modify or free ver_cstr; do not return it to the pool since it is static lifetime
// Validation: No inputs/outputs are leaked; invariants checked; static pointer not inserted into object pool.

// Enforce that input 'name' is a valid std::string reference
FUZZ_ASSERT(name != nullptr, "input name must not be null");
std::string *greeting = nullptr;
try {
    // Invoke target function with a valid, initialized std::string
    std::string res = defendnot_api::greet(*name);
    // Property: result must start with the expected prefix
    const char *prefix = "hello, ";
    bool has_prefix = res.size() >= 7 && res.compare(0, 7, prefix) == 0;
    FUZZ_ASSERT(has_prefix, "greet() must prefix 'hello, '");
    // Take ownership of the returned value by allocating a persistent std::string for the pool
    greeting = new std::string(std::move(res));
    FUZZ_ASSERT(greeting != nullptr, "allocation for greeting failed");
} catch (...) {
    // greet may throw (e.g., bad_alloc); signal to the fuzzer runtime
    FUZZ_BAIL();
}
// Output both the original input (still valid and owned by the pool) and the new greeting string
// Validation: Input preserved, new std::string produced and returned; exceptions handled via FUZZ_BAIL; prefix invariant asserted.

// Construct a new std::string using fuzzed data and return it to the pool
std::string *value = nullptr;
try {
    // Start from a fuzzed string; cap size to keep allocations bounded
    std::string seed = FUZZ_PARAM_STR();
    if (seed.size() > 1024) seed.resize(1024);

    // Vary construction paths to increase coverage and exercise API use
    unsigned int mode = static_cast<unsigned int>(*FUZZ_PARAM(unsigned int)) % 5u;
    std::string tmp;
    switch (mode) {
        case 0: // direct copy
            tmp = seed;
            break;
        case 1: // reserve + assign
            tmp.reserve(seed.size());
            tmp.assign(seed.data(), seed.size());
            break;
        case 2: { // substring prefix (including possibly empty)
            size_t cut = seed.empty() ? 0u : (static_cast<size_t>(*FUZZ_PARAM(unsigned int)) % (seed.size() + 1));
            tmp = seed.substr(0, cut);
            break;
        }
        case 3: // prefix to resemble greet input shape
            tmp = "hello, ";
            tmp += seed;
            break;
        default: // empty string case
            tmp.clear();
            break;
    }

    // Allocate persistent std::string for the object pool
    value = new std::string(std::move(tmp));
    FUZZ_ASSERT(value != nullptr, "allocation for std::string failed");

    // Track useful metadata for downstream stubs
    FUZZ_SET_ATTR_INT(value, "length", static_cast<int>(value->size()));
} catch (...) {
    // std::string operations may throw (e.g., bad_alloc)
    FUZZ_BAIL();
}
// Validation: Produces a non-null std::string*, bounded allocation, and records length attribute; no inputs to preserve.
